@dataclass(frozen=True, slots=True)
class Contract:
    customer: str  # compulsory: no default -> __init__ refuses to omit
    supplier: str

    def __post_init__(self):
        missing = [f for f in ('customer', 'supplier') if not getattr(self, f)]
        if missing:
            raise ValueError(f'compulsory properties missing: {missing}')

